INSERT INTO "FaqEntry" ("id", "questionEn", "questionAr", "answerEn", "answerAr", "category", "position")
VALUES
  ('faq-what', $faq$What is Matchena?$faq$, $faq$ماتشنا إيه؟$faq$, $faq$Matchena is a court booking and venue-management platform in Egypt. Players see live times and prices, confirm a slot, and check in with a QR code. Venue owners run the same courts from their dashboard: calendar, prices, walk-ins, staff, and earnings — football, padel, tennis, squash, PlayStation and more.$faq$, $faq$ماتشنا منصة حجز وإدارة ملاعب في مصر. اللاعب يشوف الميعاد والسعر، يأكّد الحجز، ويعمل تشيك إن بـ QR. صاحب الملعب يدير نفس الكورتات من الداشبورد: التقويم، الأسعار، حجوزات الاستقبال، الموظفين، والأرباح — كرة، بادل، تنس، اسكواش، بلايستيشن وأكتر.$faq$, 'booking', 0),
  ('faq-book', $faq$How do I book a court on Matchena?$faq$, $faq$إزاي أحجز ملعب على ماتشنا؟$faq$, $faq$Open Explore, pick a sport and area, then choose a venue. Select a free slot and duration, apply a promo or coins if you have them, and confirm. Matchena holds the slot for a few minutes while you pay from your wallet so nobody else takes it.$faq$, $faq$من استكشف اختار الرياضة والمنطقة، افتح الملعب، وحدد ميعاد فاضي والمدة. لو عندك كود خصم أو كوينز استخدمهم، وبعدين أكّد. الميعاد بيتقفّل دقايق وأنت بتدفع من المحفظة عشان محدش ياخده.$faq$, 'booking', 1),
  ('faq-sports', $faq$Which sports can I book in Egypt?$faq$, $faq$أنهي رياضات ينفع أحجزها؟$faq$, $faq$You can book football (including 5-a-side), padel, tennis, squash, basketball, volleyball, swimming, table tennis, billiards, and PlayStation lounges — whatever partner venues list as open. Filter by sport on Explore to see live availability near you.$faq$, $faq$تقدر تحجز كرة قدم (ومنها الخماسية)، بادل، تنس، اسكواش، كرة سلة، طائرة، سباحة، بينج بونج، بلياردو، وبلايستيشن — حسب الملاعب الشريكة. فلتر بالرياضة من استكشف عشان تشوف المواعيد القريبة منك.$faq$, 'booking', 2),
  ('faq-call', $faq$Do I need to call the venue to check if a slot is free?$faq$, $faq$لازم أكلّم الملعب عشان أعرف لو فاضي؟$faq$, $faq$No. Availability and the hourly price sit on the venue page. If the slot is shown as open, you can book it instantly. Confirmation holds the court — you do not need a phone call to reserve it.$faq$, $faq$لأ. المواعيد والسعر ظاهرين على صفحة الملعب. لو الميعاد فاضي، احجزه مباشرة. التأكيد بيقفل الكورت — من غير مكالمة عشان تحجز.$faq$, 'booking', 3),
  ('faq-hold', $faq$How long does Matchena hold a slot while I pay?$faq$, $faq$الميعاد بيتقفّل قد إيه وأنا بدفع؟$faq$, $faq$After you start checkout, Matchena holds the slot for a few minutes so it stays yours while the wallet payment completes. If the hold expires, the time goes back on the calendar and you can pick another slot.$faq$, $faq$أول ما تبدأ الدفع، ماتشنا بتقفل الميعاد دقايق عشان يفضل بتاعك لحد ما الدفع من المحفظة يتم. لو الوقت خلص، الميعاد يرجع على الجدول وتقدر تختار ميعاد تاني.$faq$, 'booking', 4),
  ('faq-cancel', $faq$How do I cancel a court booking?$faq$, $faq$إزاي ألغي حجز ملعب؟$faq$, $faq$Open My Bookings and cancel before the venue’s cutoff. Each listing shows its own free-cancellation window at checkout — often two or three hours before kickoff. The refund amount depends on how close you are to the slot.$faq$, $faq$من حجوزاتي اضغط إلغاء قبل ميعاد الإلغاء بتاع الملعب. كل منشأة بتظهر سياسة الإلغاء أثناء الحجز — الشائع ساعتين أو تلاتة قبل البداية. نسبة الاسترجاع بتعتمد على قربك من الميعاد.$faq$, 'booking', 5),
  ('faq-pay', $faq$How do I pay for a booking on Matchena?$faq$, $faq$أدفع حجز الملعب إزاي؟$faq$, $faq$Bookings debit your Matchena EGP wallet. Top it up with a card, Vodafone Cash, Orange Cash, Fawry, or InstaPay. Some venues also allow cash at the gate — that option appears only when the operator enables it. Never pay a random number from the venue page.$faq$, $faq$الحجوزات بتتعمل من محفظة ماتشنا بالجنيه. اشحنها ببطاقة، فودافون كاش، أورانج كاش، فوري، أو إنستاباي. بعض الملاعب بتقبل كاش عند البوابة لو المشغّل مفعّل الخيار. متدفعش على رقم عشوائي من صفحة الملعب.$faq$, 'payments', 10),
  ('faq-split', $faq$Can we split the court fee with the squad?$faq$, $faq$ينفع نقسم سعر الملعب على الفريق؟$faq$, $faq$Yes. When you confirm, add split shares for your teammates. The booking stays partial until every share is paid and the amounts add up to the total. Nobody loses the slot because one person is still collecting cash.$faq$, $faq$أيوه. وقت التأكيد ضيف حصص التقسيم لأصحابك. الحجز يفضل جزئي لحد ما كل حصة تتدفع والمبالغ تساوي الإجمالي. الميعاد مايضيعش عشان واحد لسه بيجمع الكاش.$faq$, 'payments', 11),
  ('faq-wallet', $faq$What is the Matchena wallet?$faq$, $faq$إيه محفظة ماتشنا؟$faq$, $faq$Your EGP wallet is the prepaid balance for bookings, hour bundles, and memberships. Top up once, then pay in the app. Coins are a separate rewards currency — they are not cash, and they sit next to the wallet, not inside it.$faq$, $faq$محفظة الجنيه هي رصيدك المدفوع مقدمًا للحجوزات وباقات الساعات والعضويات. اشحن مرة، وادفع من التطبيق. الكوينز عملة مكافآت منفصلة — مش فلوس نقدية، وبتظهر جنب المحفظة مش جواها.$faq$, 'payments', 12),
  ('faq-coins', $faq$How do I earn and spend Matchena coins?$faq$, $faq$الكوينز بتتجمع وتتصرف إزاي؟$faq$, $faq$Confirmed bookings, check-ins, quests, and reviews add coins. Spend them at checkout on eligible slots or on rewards like a streak freeze. Coins used on a cancelled booking return to your balance immediately.$faq$, $faq$الحجوزات المؤكدة والتشيك إن والمهام والتقييمات بتزوّد الكوينز. اصرفها وقت الحجز على المواعيد المتاحة أو على مكافآت زي تجميد الستريك. الكوينز في حجز ملغي بترجع فورًا.$faq$, 'payments', 13),
  ('faq-promo', $faq$How do promo codes work?$faq$, $faq$أكواد الخصم بتشتغل إزاي؟$faq$, $faq$Enter a valid code at checkout before you confirm. Each offer has its own discount, venue scope, dates, and usage limit. Whether a promo is restored after a cancellation depends on that offer’s terms.$faq$, $faq$اكتب الكود وقت الدفع قبل التأكيد. كل عرض له نسبة أو قيمة، ونطاق ملاعب، وتواريخ، وحد استخدام. إرجاع الكود بعد الإلغاء بيعتمد على شروط العرض نفسه.$faq$, 'payments', 14),
  ('faq-refund-time', $faq$How long do Matchena refunds take?$faq$, $faq$الاسترداد بياخد وقت قد إيه؟$faq$, $faq$Card refunds typically take 5–7 business days. Mobile wallets such as Vodafone Cash and Orange Cash usually reverse within 24–48 hours. Cash paid at the venue is settled with the operator. Full rules are on the Refund Policy page.$faq$, $faq$استرداد البطاقة خلال 5 إلى 7 أيام عمل. محافظ الموبايل زي فودافون كاش وأورانج كاش عادةً خلال 24 إلى 48 ساعة. الكاش في الملعب بيتحسم مع المشغّل. التفاصيل الكاملة في سياسة الاسترداد.$faq$, 'payments', 15),
  ('faq-account', $faq$How do I create a Matchena account?$faq$, $faq$إزاي أعمل حساب على ماتشنا؟$faq$, $faq$Register with your mobile number — we send a one-time code — or continue with Google or Facebook. On supported devices you can unlock Face ID or a passkey so the next visit skips SMS. One account books courts, joins squads, and plays tonight.$faq$, $faq$سجّل برقم الموبايل — هيبعتلك كود مرة واحدة — أو كمّل بجوجل أو فيسبوك. وعلى الأجهزة المدعومة تقدر تفعّل Face ID أو passkey عشان الزيارة الجاية من غير SMS. حساب واحد للحجز والسكواد واللعب.$faq$, 'account', 20),
  ('faq-otp', $faq$I did not receive the login OTP. What should I do?$faq$, $faq$كود الدخول مش واصل. أعمل إيه؟$faq$, $faq$Use an Egyptian number in +20 format and wait about a minute. Check coverage and that the SMS was not filtered. Request a new code, or skip the wait and sign in with Google, Facebook, or Face ID.$faq$, $faq$استخدم رقم مصري بصيغة +20 واستنى حوالي دقيقة. اتأكد من الشبكة وإن الرسالة متفلترتش. اطلب كود جديد، أو ادخل مباشرة بجوجل أو فيسبوك أو Face ID.$faq$, 'account', 21),
  ('faq-oauth', $faq$Can I sign in with Google, Facebook, or Face ID?$faq$, $faq$ينفع أدخل بجوجل أو فيسبوك أو Face ID؟$faq$, $faq$Yes. Google and Facebook are on the login screen. On supported browsers and devices you can add a passkey or Face ID so the next visit skips the SMS code. Your bookings stay on the same Matchena account.$faq$, $faq$أيوه. جوجل وفيسبوك موجودين في شاشة الدخول. وعلى المتصفحات والأجهزة المدعومة تقدر تضيف passkey أو Face ID عشان الزيارة الجاية من غير كود SMS. حجوزاتك بتفضل على نفس حساب ماتشنا.$faq$, 'account', 22),
  ('faq-qr', $faq$How does QR check-in work at the venue?$faq$, $faq$التشيك إن بالـ QR بيتم إزاي؟$faq$, $faq$After the booking is confirmed you get a QR on the booking screen. Show it at the gate — the venue scans it and you are checked in. After the session you can review the venue; confirmed bookings and check-ins add coins.$faq$, $faq$بعد تأكيد الحجز هتلاقي QR على شاشة الحجز. اعرضه عند البوابة — الملعب بيمسحه وأنت اتشك إن. بعد الجلسة تقدر تقيّم الملعب، والحجوزات المؤكدة والتشيك إن بتزوّد الكوينز.$faq$, 'play', 30),
  ('faq-pulse', $faq$What is Pulse if my match is one player short?$faq$, $faq$إيه Pulse ولو الماتش ناقص؟$faq$, $faq$Pulse surfaces open matches that still need players in your country. Post a match, claim a spot, or invite your squad. Confirm only if you can attend — repeated late cancellations lower your reliability score.$faq$, $faq$Pulse بيظهر الماتشات المفتوحة اللي لسه محتاجة لاعيبة في نفس البلد. انشر ماتش، احجز مكان، أو ادعُ سكوادك. أكّد بس لو هتحضر — الإلغاء المتأخر المتكرر بيقلل درجة الالتزام.$faq$, 'play', 31),
  ('faq-squad', $faq$How do squads and lobby invites work?$faq$, $faq$السكواد ودعوات اللوبي بتشتغل إزاي؟$faq$, $faq$Create or join a squad, then invite friends to the lobby before you book. You can split the fee, share a hold link, and keep the group in one thread. If you are not free, decline — you can pause someone’s invites for a few minutes.$faq$, $faq$اعمل سكواد أو انضم لواحد، وبعدين ادعُ أصحابك للوبي قبل الحجز. تقدروا تقسموا الفاتورة، تشاركوا لينك الحجز، وتفضلوا في محادثة واحدة. لو مش فاضي، ارفض — وينفع توقف دعوات حد لدقايق.$faq$, 'play', 32),
  ('faq-reliability', $faq$What is the reliability score on Matchena?$faq$, $faq$درجة الالتزام دي إيه؟$faq$, $faq$Reliability reflects whether you show up after you confirm. No-shows and late cancellations can lower it. A strong score helps you get accepted into open matches and keeps captains confident when they invite you.$faq$, $faq$درجة الالتزام بتعكس إنك بتحضر بعد التأكيد. عدم الحضور والإلغاء المتأخر ممكن يقللوها. الدرجة العالية بتسهّل قبولك في الماتشات المفتوحة، وبتخلي الكابتن يطمّن وهو بيوجهلك دعوة.$faq$, 'play', 33),
  ('faq-open-match', $faq$How do I join an open match?$faq$, $faq$إزاي أنضم لماتش مفتوح؟$faq$, $faq$Go to Community, open Pulse or the matches tab, and claim a spot on a game that still needs players. Read the time, area, and cost per player before you confirm. Keep chat and payment inside Matchena.$faq$, $faq$من المجتمع افتح Pulse أو تبويب الماتشات، واحجز مكان في ماتش لسه ناقص لاعيبة. اقرأ الميعاد والمنطقة وتكلفة اللاعب قبل التأكيد. خلّي الشات والدفع جوه ماتشنا.$faq$, 'play', 34),
  ('faq-membership', $faq$Can I buy a membership or an hour bundle?$faq$, $faq$ينفع أشتري عضوية أو باقة ساعات؟$faq$, $faq$Where a venue offers them, you can buy hour bundles or a monthly membership from the listing and pay from your EGP wallet. Included hours and renewal dates sit on your account. Cancel a membership from the membership screen before the next renewal.$faq$, $faq$لو الملعب موفّر باقات ساعات أو عضوية شهرية، اشتريها من صفحة المنشأة وادفع من محفظة الجنيه. الساعات المتبقية وميعاد التجديد ظاهرين على حسابك. إلغاء العضوية من شاشة العضوية قبل التجديد الجاي.$faq$, 'play', 35),
  ('faq-list-venue', $faq$How do I list my venue on Matchena?$faq$, $faq$إزاي أضيف ملعبي على ماتشنا؟$faq$, $faq$Apply from the Partners page with your courts, hours, prices, and cancellation window. After verification, the owner dashboard is yours: today’s schedule, bookings, pricing, staff, and earnings. Players book from the app without calling you.$faq$, $faq$قدّم من صفحة الشركاء بالكورتات والمواعيد والأسعار وسياسة الإلغاء. بعد الاعتماد، داشبورد المالك تبقى بتاعتك: جدول النهارده، الحجوزات، التسعير، الموظفين، والأرباح. اللاعب يحجز من التطبيق من غير ما يكلّمك.$faq$, 'owners', 40),
  ('faq-owner-payout', $faq$How do venue owners get paid?$faq$, $faq$صاحب الملعب بيستلم فلوسه إزاي؟$faq$, $faq$Online bookings settle through Matchena according to your partner terms. Add a bank account, InstaPay, or mobile wallet in owner settings — identifiers are stored masked. Cash taken at the door is reconciled with you directly.$faq$, $faq$حجوزات الأونلاين بتتسوّى عن طريق ماتشنا حسب شروط الشراكة. أضف حساب بنكي أو إنستاباي أو محفظة من إعدادات المالك — الرقم بيتخزن مقنّع. الكاش عند الباب بيتحسم معاك مباشرة.$faq$, 'owners', 41),
  ('faq-owner-cancel', $faq$Can a venue owner cancel a player’s Matchena booking?$faq$, $faq$كصاحب ملعب أقدر ألغي حجز لاعب من ماتشنا؟$faq$, $faq$Platform bookings belong to the player too, so you cannot cancel or move them yourself. Send a change or cancel request from the booking — Matchena admin is notified and the player is kept in the loop.$faq$, $faq$حجز ماتشنا ملك اللاعب كمان، فمتقدرش تلغيه أو تعدّله لوحدك. ابعت طلب تغيير أو إلغاء من الحجز — الإدارة بتتنبه، واللاعب بيفضل في الصورة.$faq$, 'owners', 42),
  ('faq-owner-dashboard', $faq$What can I run from the venue owner dashboard?$faq$, $faq$أقدر أدير إيه من داشبورد صاحب الملعب؟$faq$, $faq$The owner dashboard is the operating system for your courts. Today shows who is coming. You add a walk-in or phone booking, block a slot, scan a QR, and mark who showed up. From the same account you edit venues and prices, run promotions and tournaments, reply to reviews, invite staff, and read earnings.$faq$, $faq$داشبورد المالك هي تشغيل الملعب. صفحة النهارده بتوريك مين جاي. تضيف حجز استقبال أو تليفون، تقفل ميعاد، تمسح QR، وتعلّم مين حضر. ومن نفس الحساب تعدّل الملاعب والأسعار، تشغّل العروض والبطولات، ترد على التقييمات، تدعو الموظفين، وتتابع الأرباح.$faq$, 'owners', 43),
  ('faq-owner-walkin', $faq$How do I add a walk-in or phone booking?$faq$, $faq$إزاي أسجّل حجز استقبال أو تليفون؟$faq$, $faq$On Today, start a new booking, pick the court and slot, and mark how it came in — walk-in, phone, or WhatsApp — and whether it is paid. The slot leaves the public calendar so a player on Matchena cannot take it twice.$faq$, $faq$من صفحة النهارده ابدأ حجز جديد، اختار الكورت والميعاد، وحدّد المصدر: استقبال، تليفون، أو واتساب، وهل اتدفع. الميعاد يتشال من الجدول العام عشان لاعب على ماتشنا ماياخدوش مرتين.$faq$, 'owners', 44),
  ('faq-owner-block', $faq$How do I close a court slot?$faq$, $faq$إزاي أقفل ميعاد على الملعب؟$faq$, $faq$Block the time from Today when the court is in maintenance or a private session. A blocked slot is not bookable on Explore. Unblock it when the court is open again.$faq$, $faq$اقفل الميعاد من صفحة النهارده لو الكورت في صيانة أو جلسة خاصة. الميعاد المقفول مش قابل للحجز من استكشف. افتحه تاني لما الملعب يرجع متاح.$faq$, 'owners', 45),
  ('faq-owner-staff', $faq$How do staff accounts work?$faq$, $faq$حسابات الموظفين بتشتغل إزاي؟$faq$, $faq$Invite staff by email and give each person only the access they need: view bookings, check players in, manage prices, or read reports. You can suspend or remove access from the Staff screen without sharing your owner login.$faq$, $faq$ادعُ الموظف بالإيميل وادّيله الصلاحية اللي محتاجها بس: يشوف الحجوزات، يعمل تشيك إن، يدير الأسعار، أو يقرأ التقارير. تقدر توقف أو تشيل الصلاحية من شاشة الموظفين من غير ما تشارك دخول المالك.$faq$, 'owners', 46),
  ('faq-owner-scan', $faq$How does the venue scan a player’s QR?$faq$, $faq$الملعب بيمسح QR اللاعب إزاي؟$faq$, $faq$Open Scan from the owner dashboard and point it at the code on the player’s booking. A valid code checks them in for that slot. After the session, mark the booking as attended or as a no-show.$faq$, $faq$افتح المسح من داشبورد المالك ووجّهه على الكود في حجز اللاعب. الكود السليم بيعمل تشيك إن للميعاد ده. بعد الجلسة علّم الحجز حضر أو ما حضرش.$faq$, 'owners', 47),
  ('faq-policy', $faq$What is Matchena’s cancellation and refund policy?$faq$, $faq$سياسة الإلغاء والاسترداد في ماتشنا إيه؟$faq$, $faq$Each venue sets its cancellation window and shows it on the listing and at checkout. Cancel in time for a refund to wallet, card, or e-wallet as described on the Refund Policy page. After the cutoff, the booking is charged.$faq$, $faq$كل ملعب بيحدد ميعاد الإلغاء، وبيظهر في صفحة المنشأة وأثناء الحجز. لو ألغيت في الوقت، الاسترداد للمحفظة أو البطاقة أو الكاش حسب سياسة الاسترداد. بعد الميعاد، الحجز بيتخصم.$faq$, 'policies', 50),
  ('faq-noshow', $faq$What happens if I confirm and do not show up?$faq$, $faq$لو أكّدت الحجز ومظهرتش بيحصل إيه؟$faq$, $faq$A no-show is not refunded. The venue keeps the slot, and your reliability score may drop. If something went wrong at the gate, write to support@matchena.com within 48 hours with your booking code.$faq$, $faq$عدم الحضور من غير استرداد. الملعب يحتفظ بالميعاد، ودرجة الالتزام ممكن تقل. لو حصلت مشكلة عند البوابة، ابعت support@matchena.com خلال 48 ساعة ومعاك رقم الحجز.$faq$, 'policies', 51),
  ('faq-cities', $faq$Where can I book a court with Matchena?$faq$, $faq$ماتشنا شغالة في أنهي مدن؟$faq$, $faq$Matchena is live in Egypt. Partner venues appear on Explore as they go live — Greater Cairo first, then more areas. Filter by sport and neighbourhood to see who is actually accepting bookings today.$faq$, $faq$ماتشنا شغالة في مصر. الملاعب الشريكة بتظهر في استكشف أول ما تفعّل — القاهرة الكبرى أولاً وبعدين مناطق أكتر. فلتر بالرياضة والحي عشان تشوف مين بيستقبل حجز النهارده.$faq$, 'policies', 52),
  ('faq-contact', $faq$How do I contact Matchena support?$faq$, $faq$إزاي أتواصل مع دعم ماتشنا؟$faq$, $faq$Use the Contact page or email support@matchena.com with your booking code, venue, and slot time. We do not publish a public phone number. Logged-in messages are linked to your account so we can trace the booking faster.$faq$, $faq$من صفحة تواصل معنا أو على support@matchena.com، ومعاك رقم الحجز والملعب والميعاد. مفيش رقم هاتف عام. لو أنت مسجّل، الرسالة بتتربط بحسابك عشان نلاقي الحجز أسرع.$faq$, 'policies', 53)
