-- Refresh Help Center copy so players and venue owners are both covered.
-- Idempotent upsert. The category column already exists.

ON CONFLICT ("id") DO UPDATE SET
  "questionEn" = EXCLUDED."questionEn",
  "questionAr" = EXCLUDED."questionAr",
  "answerEn" = EXCLUDED."answerEn",
  "answerAr" = EXCLUDED."answerAr",
  "category" = EXCLUDED."category",
  "position" = EXCLUDED."position";
